use atlas_native_storage_contract::{create_workspace,add_file,replace_file};use std::{fs,path::{Path,PathBuf},time::{SystemTime,UNIX_EPOCH}};use rusqlite::Connection;
fn root()->PathBuf{std::env::temp_dir().join(format!("atlas-replace-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()))}
fn info(p:&Path,id:&str)->(String,String){Connection::open(p.join("atlas.sqlite3")).unwrap().query_row("SELECT o.path,s.body FROM objects o JOIN search_index s ON o.id=s.object_id WHERE o.id=?",[id],|r|Ok((r.get(0)?,r.get(1)?))).unwrap()}
#[test]fn same_name_replace_uses_new_physical_path(){let p=root();create_workspace(&p).unwrap();let id=add_file(&p,"same.txt",b"oldunique").unwrap();let(old,_)=info(&p,&id);replace_file(&p,&id,"same.txt",b"newunique").unwrap();let(new,body)=info(&p,&id);assert_eq!(fs::read(p.join(&new)).unwrap(),b"newunique");assert_eq!(body,"newunique");assert_ne!(old,new,"a replacement must not overwrite the referenced file before commit");fs::remove_dir_all(p).unwrap();}
#[test]fn db_failure_preserves_same_name_original(){let p=root();create_workspace(&p).unwrap();let id=add_file(&p,"same.txt",b"oldunique").unwrap();let(path,_)=info(&p,&id);Connection::open(p.join("atlas.sqlite3")).unwrap().execute_batch("CREATE TRIGGER fail_replace BEFORE UPDATE ON objects BEGIN SELECT RAISE(ABORT,'injected failure'); END;").unwrap();assert!(replace_file(&p,&id,"same.txt",b"newunique").is_err());let(new_path,body)=info(&p,&id);assert_eq!(new_path,path);assert_eq!(fs::read(p.join(path)).unwrap(),b"oldunique");assert_eq!(body,"oldunique");fs::remove_dir_all(p).unwrap();}
#[test]fn index_failure_rolls_back_new_path(){let p=root();create_workspace(&p).unwrap();let id=add_file(&p,"one.txt",b"oldunique").unwrap();let(path,_)=info(&p,&id);Connection::open(p.join("atlas.sqlite3")).unwrap().execute_batch("DROP TABLE search_chunks").unwrap();assert!(replace_file(&p,&id,"two.txt",b"newunique").is_err());let(current,body)=info(&p,&id);assert_eq!(current,path);assert_eq!(fs::read(p.join(path)).unwrap(),b"oldunique");assert_eq!(body,"oldunique");fs::remove_dir_all(p).unwrap();}
